import { z } from "zod";
const zFilter = z
    .object({
    // Component targeting - these are used as filters to determine which events to listen to
    componentType: z.string(), // 'series', 'legend', 'xAxis', 'yAxis', etc.
    seriesIndex: z.number(),
    seriesName: z.string(),
    // Data targeting
    dataIndex: z.number(),
    name: z.string(), // data item name
    dataType: z.string(), // 'node', 'edge' for graphs
})
    .partial();
const zEvent = z.object({}).passthrough();
const zEChartsProps = z.object({
    options: z.any(), // ECharts configuration object - too complex to validate
    aspectRatio: z.number().optional(), // Optional aspect ratio override
    label: z.string().optional(),
    caption: z.string().optional(),
    size: z.enum(["s", "m", "l", "stretch"]).nullish(),
    appearance: z.enum(["default", "card", "well"]).default("default").optional(),
    events: z
        .object({
        click: z
            .union([
            z.boolean(),
            z.record(z.string(), zFilter), // { id: filter }
        ])
            .default({
            "data-interaction": { componentType: "series" },
        }),
        select: z
            .union([
            z.boolean(),
            z.record(z.string(), zFilter), // { id: filter }
        ])
            .default(true),
    })
        .optional(),
});
export function EChartsWidget(define) {
    return define("EChartsWidget")
        .props(zEChartsProps)
        .userEvents({
        click: [zEvent, null],
        select: [zEvent, null],
    })
        .render((props) => {
        return {
            id: props.id,
            label: props.label,
            caption: props.caption,
            size: props.size,
            appearance: props.appearance,
            options: props.options,
            aspectRatio: props.aspectRatio,
            events: props.events,
        };
    });
}
